-- 027_sale_items_discounts.sql
-- Sales discounts (BUSINESS_RULES 13C), part 1 of 2: POS goods lines. GENERATED by server/src/db/gen/sales-discounts-sql.ts; do not edit.
-- Rebuilds sale_items because its table CHECK (revenue_cents = qty * unit_price_cents) must become
--   revenue = qty x unit_price - line_discount - bill_discount
-- and SQLite cannot alter a table CHECK. Adds five NOT NULL columns: list_unit_price_cents (existing rows: = unit_price_cents),
-- unit_discount_cents, line_discount_cents, price_reduction_cents, bill_discount_cents (existing rows: 0), with the CHECKs listed in the
-- table definition. Every other column value, id and the AUTOINCREMENT counter are preserved exactly.
-- Same technique as 015 / 023 / 025: the runner executes the file in a transaction with foreign_keys ON, so the table is parked in a TEMP
-- table, dropped, re-created under its own name and re-filled with the same ids (dropping the parent counts the sales_return_items rows as
-- deferred violations; re-inserting the same ids clears them). Dropping a table drops its indexes and triggers, so EVERY index and trigger is
-- re-created (text copied verbatim from a schema-26 database; trg_sale_items_immutable also covers the new columns).
-- New triggers: trg_sale_items_telecom_no_discount (a Telecom sale line, every segment, refuses any discount and any list price other than
-- its price) and trg_sale_items_list_price_default (compatibility: an INSERT that does not name list_unit_price_cents gets the DEFAULT -1,
-- the "not supplied" marker, and this AFTER INSERT trigger sets it to unit_price_cents, so code written before discounts keeps working;
-- -1 can never remain stored). The migration aborts (rolls back) if any row differs, a foreign key is broken, the set of indexes and triggers
-- is not exactly the old set plus the two new triggers, or ANY object outside sale_items (the return triggers that read it included) changed.

PRAGMA defer_foreign_keys = ON;

-- everything the migration must leave alone, and every object of the table that must come back
CREATE TEMP TABLE _mig027_other AS
SELECT type, name, tbl_name, sql FROM sqlite_master WHERE tbl_name <> 'sale_items' AND name NOT LIKE 'sqlite_%';
CREATE TEMP TABLE _mig027_objs AS
SELECT type, name, tbl_name FROM sqlite_master
 WHERE tbl_name = 'sale_items' AND type IN ('index','trigger') AND name NOT LIKE 'sqlite_autoindex%';

CREATE TEMP TABLE _mig027_rows AS SELECT id, sale_id, line_no, line_type, product_id, description, qty, unit_price_cents, unit_cost_cents, revenue_cents, cogs_cents, returned_qty, extra_cost_cents FROM sale_items;
CREATE TEMP TABLE _mig027_seq AS SELECT COALESCE((SELECT seq FROM sqlite_sequence WHERE name = 'sale_items'), 0) AS seq;

DROP TABLE sale_items;

CREATE TABLE sale_items (
  id                INTEGER PRIMARY KEY AUTOINCREMENT,
  sale_id           INTEGER NOT NULL REFERENCES sales(id),
  line_no           INTEGER NOT NULL CHECK (line_no >= 1),
  line_type         TEXT    NOT NULL CHECK (line_type IN ('goods','card')),
  product_id        INTEGER NOT NULL REFERENCES products(id),
  description       TEXT    NOT NULL,
  qty               INTEGER NOT NULL CHECK (qty >= 1),
  unit_price_cents  INTEGER NOT NULL CHECK (unit_price_cents >= 0),
  unit_cost_cents   INTEGER NOT NULL CHECK (unit_cost_cents >= 0),
  revenue_cents     INTEGER NOT NULL CHECK (revenue_cents >= 0),
  cogs_cents        INTEGER NOT NULL CHECK (cogs_cents >= 0),
  returned_qty      INTEGER NOT NULL DEFAULT 0, extra_cost_cents INTEGER NOT NULL DEFAULT 0 CHECK (extra_cost_cents >= 0),
  list_unit_price_cents INTEGER NOT NULL DEFAULT -1 CHECK (list_unit_price_cents >= -1),
  unit_discount_cents   INTEGER NOT NULL DEFAULT 0 CHECK (unit_discount_cents >= 0),
  line_discount_cents   INTEGER NOT NULL DEFAULT 0 CHECK (line_discount_cents >= 0),
  price_reduction_cents INTEGER NOT NULL DEFAULT 0 CHECK (price_reduction_cents >= 0),
  bill_discount_cents   INTEGER NOT NULL DEFAULT 0 CHECK (bill_discount_cents >= 0),
  UNIQUE (sale_id, line_no),
  -- section 13C: the amount paid is the gross line minus the per-unit discounts minus the line's share of the whole-bill discount
  CHECK (revenue_cents = qty * unit_price_cents - line_discount_cents - bill_discount_cents),
  CHECK (unit_discount_cents <= unit_price_cents),
  CHECK (line_discount_cents = unit_discount_cents * qty),
  -- the automatic price reduction: typed price below the list price (a higher typed price is an ordinary price, no reduction)
  CHECK (price_reduction_cents = qty * CASE WHEN list_unit_price_cents > unit_price_cents THEN list_unit_price_cents - unit_price_cents ELSE 0 END),
  -- you cannot take back more than you sold
  CHECK (returned_qty BETWEEN 0 AND qty)
);

-- the triggers are re-created only after the copy, so none of them fires while the rows are copied back
INSERT INTO sale_items (id, sale_id, line_no, line_type, product_id, description, qty, unit_price_cents, unit_cost_cents, revenue_cents, cogs_cents, returned_qty, extra_cost_cents, list_unit_price_cents, unit_discount_cents, line_discount_cents, price_reduction_cents, bill_discount_cents)
SELECT id, sale_id, line_no, line_type, product_id, description, qty, unit_price_cents, unit_cost_cents, revenue_cents, cogs_cents, returned_qty, extra_cost_cents, unit_price_cents, 0, 0, 0, 0 FROM _mig027_rows ORDER BY id;

UPDATE sqlite_sequence SET seq = max(seq, (SELECT seq FROM _mig027_seq)) WHERE name = 'sale_items';

-- ===== indexes and triggers of schema 26 (verbatim; only the immutable trigger is extended) =====
CREATE INDEX idx_sale_items_product ON sale_items(product_id);

CREATE INDEX idx_sale_items_sale ON sale_items(sale_id);

CREATE TRIGGER trg_sale_items_book_mismatch
BEFORE INSERT ON sale_items
WHEN NOT EXISTS (
  SELECT 1 FROM sales s JOIN products p ON p.id = NEW.product_id
   WHERE s.id = NEW.sale_id
     AND p.book = s.book
     AND ((NEW.line_type = 'goods' AND s.book = 'shop') OR (NEW.line_type = 'card' AND s.book = 'telecom')))
BEGIN
  SELECT RAISE(ABORT, 'SALE_ITEM_BOOK_MISMATCH');
END;

CREATE TRIGGER trg_sale_items_extra_cost_immutable
BEFORE UPDATE OF extra_cost_cents ON sale_items
WHEN NEW.extra_cost_cents IS NOT OLD.extra_cost_cents
BEGIN
  SELECT RAISE(ABORT, 'SALE_ITEM_IMMUTABLE');
END;

CREATE TRIGGER trg_sale_items_immutable
BEFORE UPDATE ON sale_items
WHEN NEW.id IS NOT OLD.id
  OR NEW.sale_id IS NOT OLD.sale_id
  OR NEW.line_no IS NOT OLD.line_no
  OR NEW.line_type IS NOT OLD.line_type
  OR NEW.product_id IS NOT OLD.product_id
  OR NEW.description IS NOT OLD.description
  OR NEW.qty IS NOT OLD.qty
  OR NEW.unit_price_cents IS NOT OLD.unit_price_cents
  OR NEW.unit_cost_cents IS NOT OLD.unit_cost_cents
  OR NEW.revenue_cents IS NOT OLD.revenue_cents
  OR NEW.cogs_cents IS NOT OLD.cogs_cents
  OR NEW.unit_discount_cents IS NOT OLD.unit_discount_cents
  OR NEW.line_discount_cents IS NOT OLD.line_discount_cents
  OR NEW.price_reduction_cents IS NOT OLD.price_reduction_cents
  OR NEW.bill_discount_cents IS NOT OLD.bill_discount_cents
  OR (NEW.list_unit_price_cents IS NOT OLD.list_unit_price_cents
      AND NOT (OLD.list_unit_price_cents = -1 AND NEW.list_unit_price_cents = OLD.unit_price_cents))
  OR (NEW.returned_qty < OLD.returned_qty
      AND (NEW.returned_qty IS NOT (
             SELECT COALESCE(SUM(ri.qty), 0)
               FROM sales_return_items ri JOIN sales_returns r ON r.id = ri.sales_return_id
              WHERE ri.sale_item_id = OLD.id AND r.status = 'posted')
           OR NOT EXISTS (
             SELECT 1 FROM sales_return_items ri JOIN sales_returns r ON r.id = ri.sales_return_id
              WHERE ri.sale_item_id = OLD.id AND r.status = 'void')))
BEGIN
  SELECT RAISE(ABORT, 'SALE_ITEM_IMMUTABLE');
END;

CREATE TRIGGER trg_sale_items_no_delete
BEFORE DELETE ON sale_items
BEGIN
  SELECT RAISE(ABORT, 'RECORD_DELETE_FORBIDDEN');
END;

CREATE TRIGGER trg_sale_items_segment_matches
BEFORE INSERT ON sale_items
WHEN EXISTS (SELECT 1 FROM sales s JOIN v_product_segment v ON v.product_id = NEW.product_id
              WHERE s.id = NEW.sale_id AND (v.book IS NOT s.book OR v.segment IS NOT s.segment))
BEGIN
  SELECT RAISE(ABORT, 'SEGMENT_MISMATCH');
END;

-- ===== new objects =====
-- Telecom sale lines (every segment) are never discounted and are always sold at the list price
CREATE TRIGGER trg_sale_items_telecom_no_discount
BEFORE INSERT ON sale_items
WHEN (NEW.unit_discount_cents <> 0 OR NEW.line_discount_cents <> 0 OR NEW.price_reduction_cents <> 0 OR NEW.bill_discount_cents <> 0
      OR (NEW.list_unit_price_cents <> -1 AND NEW.list_unit_price_cents <> NEW.unit_price_cents))
  AND EXISTS (SELECT 1 FROM sales s WHERE s.id = NEW.sale_id AND s.book = 'telecom')
BEGIN
  SELECT RAISE(ABORT, 'DISCOUNT_NOT_ALLOWED');
END;

-- compatibility: a line inserted without a list price (the -1 default) is sold at its own price
CREATE TRIGGER trg_sale_items_list_price_default
AFTER INSERT ON sale_items
WHEN NEW.list_unit_price_cents = -1
BEGIN
  UPDATE sale_items SET list_unit_price_cents = NEW.unit_price_cents WHERE id = NEW.id;
END;

-- ===== guard: any difference aborts (and so rolls back) the whole migration =====
CREATE TEMP TABLE _mig027_new (name TEXT NOT NULL);
INSERT INTO _mig027_new VALUES ('trg_sale_items_telecom_no_discount');
INSERT INTO _mig027_new VALUES ('trg_sale_items_list_price_default');
CREATE TEMP TABLE _mig027_guard (ok INTEGER NOT NULL CHECK (ok = 1));
INSERT INTO _mig027_guard SELECT CASE WHEN
  (SELECT COUNT(*) FROM sale_items) = (SELECT COUNT(*) FROM _mig027_rows)
 AND   NOT EXISTS (SELECT 1 FROM _mig027_rows o LEFT JOIN sale_items n ON n.id = o.id WHERE n.id IS NULL
                      OR n.id IS NOT o.id
                      OR n.sale_id IS NOT o.sale_id
                      OR n.line_no IS NOT o.line_no
                      OR n.line_type IS NOT o.line_type
                      OR n.product_id IS NOT o.product_id
                      OR n.description IS NOT o.description
                      OR n.qty IS NOT o.qty
                      OR n.unit_price_cents IS NOT o.unit_price_cents
                      OR n.unit_cost_cents IS NOT o.unit_cost_cents
                      OR n.revenue_cents IS NOT o.revenue_cents
                      OR n.cogs_cents IS NOT o.cogs_cents
                      OR n.returned_qty IS NOT o.returned_qty
                      OR n.extra_cost_cents IS NOT o.extra_cost_cents
                      OR n.list_unit_price_cents IS NOT o.unit_price_cents
                      OR n.unit_discount_cents IS NOT 0
                      OR n.line_discount_cents IS NOT 0
                      OR n.price_reduction_cents IS NOT 0
                      OR n.bill_discount_cents IS NOT 0)
 AND   (SELECT seq FROM sqlite_sequence WHERE name = 'sale_items') >= (SELECT seq FROM _mig027_seq)
 AND   NOT EXISTS (SELECT 1 FROM pragma_foreign_key_check)
 AND   NOT EXISTS (SELECT 1 FROM _mig027_objs o WHERE NOT EXISTS (SELECT 1 FROM sqlite_master m WHERE m.type = o.type AND m.name = o.name AND m.tbl_name = o.tbl_name))
 AND   NOT EXISTS (SELECT 1 FROM _mig027_new w WHERE NOT EXISTS (SELECT 1 FROM sqlite_master m WHERE m.type = 'trigger' AND m.name = w.name AND m.tbl_name = 'sale_items'))
 AND   (SELECT COUNT(*) FROM sqlite_master WHERE tbl_name = 'sale_items' AND type IN ('index','trigger') AND name NOT LIKE 'sqlite_autoindex%') = (SELECT COUNT(*) FROM _mig027_objs) + (SELECT COUNT(*) FROM _mig027_new)
 AND   (SELECT COUNT(*) FROM sqlite_master WHERE tbl_name <> 'sale_items' AND name NOT LIKE 'sqlite_%') = (SELECT COUNT(*) FROM _mig027_other)
 AND   NOT EXISTS (SELECT 1 FROM _mig027_other o LEFT JOIN sqlite_master m ON m.type = o.type AND m.name = o.name WHERE m.name IS NULL OR m.tbl_name IS NOT o.tbl_name OR m.sql IS NOT o.sql)
  THEN 1 ELSE 0 END;

DROP TABLE _mig027_guard;
DROP TABLE _mig027_new;
DROP TABLE _mig027_other;
DROP TABLE _mig027_objs;
DROP TABLE _mig027_seq;
DROP TABLE _mig027_rows;
